// Generates Tests/ChordCoreTests/FrameLandmarkFixtures.swift.
//
// Every landmark t is found by bisecting frame() itself. No landmark value
// is typed by hand. Run scripts/generate-frame-fixtures.sh; do not edit the
// generated file.

let resolutions: [(name: String, w: Double, h: Double)] = [
    ("1280x720", 1280, 720),
    ("1366x768", 1366, 768),
    ("1440x900", 1440, 900),
    ("2560x1440", 2560, 1440),
    ("3840x2160", 3840, 2160),
]

// Target ratios are definitions. The t values they map to are not.
let targets: [(name: String, ratio: Double)] = [
    ("square", 1),
    ("fourByThree", 4.0 / 3.0),
    ("threeByTwo", 3.0 / 2.0),
    ("goldenRectangle", Unfold.phi),
]

/// Finds the t in [knot, 1] where frame(t).ratio == target by bisection.
/// frame(t).ratio is monotonic increasing on that segment, so bisection is exact up to
/// floating-point precision.
func landmarkT(target: Double, screenW: Double, screenH: Double) -> Double {
    var lo = Unfold.knot
    var hi = 1.0
    let below = frame(lo, screenW: screenW, screenH: screenH).ratio
    let above = frame(hi, screenW: screenW, screenH: screenH).ratio
    precondition(below < target && target < above, "target ratio not bracketed by segment 1")
    for _ in 0..<200 {
        let mid = (lo + hi) / 2
        if mid == lo || mid == hi { break }
        if frame(mid, screenW: screenW, screenH: screenH).ratio < target {
            lo = mid
        } else {
            hi = mid
        }
    }
    return (lo + hi) / 2
}

print("// GENERATED by scripts/generate-frame-fixtures.sh from frame(). Do not edit.")
print("")
print("struct FrameLandmark {")
print("    let screenW: Double")
print("    let screenH: Double")
print("    let name: String")
print("    let ratio: Double")
print("    let t: Double")
print("    let w: Double")
print("    let h: Double")
print("}")
print("")
print("let frameLandmarks: [FrameLandmark] = [")
for resolution in resolutions {
    for target in targets {
        let t = landmarkT(target: target.ratio, screenW: resolution.w, screenH: resolution.h)
        let f = frame(t, screenW: resolution.w, screenH: resolution.h)
        print("    FrameLandmark(screenW: \(resolution.w), screenH: \(resolution.h), name: \"\(target.name)\", ratio: \(target.ratio), t: \(t), w: \(f.w), h: \(f.h)),")
    }
}
print("]")
